adcs_vec3_t u;
double dot_product;
double req_norm;
double perp_norm;

/* Check for NULL pointers */
if ((request == NULL) || (field == NULL) || (parallel == NULL) || 
    (perpendicular == NULL) || (fraction == NULL)) {
    return ADCS_E_NULL;
}

/* Initialize outputs to zero for failure case as per requirement */
*parallel = (adcs_vec3_t){0.0, 0.0, 0.0};
*perpendicular = (adcs_vec3_t){0.0, 0.0, 0.0};
*fraction = 0.0;

/* Check for non-finite inputs */
if (!adcs_is_finite_vec3(request) || !adcs_is_finite_vec3(field)) {
    return ADCS_E_NOT_FINITE;
}

/* Normalize the magnetic field vector */
if (adcs_vec3_normalize(field, ADCS_EPS_NORM, &u) != ADCS_OK) {
    return ADCS_E_DEGENERATE;
}

/* Compute parallel component: (request . u) * u */
dot_product = adcs_vec3_dot(request, &u);
*parallel = adcs_vec3_scale(&u, dot_product);

/* Compute perpendicular component: request - parallel */
*perpendicular = adcs_vec3_sub(request, parallel);

/* Compute controllable fraction */
req_norm = adcs_vec3_norm(request);

if (req_norm <= 0.0) {
    /* Zero request results in zero fraction */
    *fraction = 0.0;
} else {
    perp_norm = adcs_vec3_norm(perpendicular);
    *fraction = perp_norm / req_norm;
}

return ADCS_OK;

