adcs_vec3_t u;
double norm_field, norm_request, dot_product, fraction_val;
adcs_vec3_t parallel_part, perpendicular_part;

/* 1. Check for NULL pointers */
if ((request == NULL) || (field == NULL) || (parallel == NULL) || 
    (perpendicular == NULL) || (fraction == NULL)) {
    return ADCS_E_NULL;
}

/* 2. Check for non-finite values */
if (!adcs_is_finite_vec3(request) || !adcs_is_finite_vec3(field)) {
    return ADCS_E_DEGENERATE;
}

/* 3. Normalize field to get u */
norm_field = adcs_vec3_norm(field);
if (norm_field <= ADCS_EPS_NORM) {
    return ADCS_E_DEGENERATE;
}

/* Compute unit vector u = field / norm_field */
u = adcs_vec3_scale(field, 1.0 / norm_field);

/* 4. Calculate parallel component: (request . u) * u */
dot_product = adcs_vec3_dot(request, &u);
parallel_part = adcs_vec3_scale(&u, dot_product);

/* 5. Calculate perpendicular component: request - parallel */
perpendicular_part = adcs_vec3_sub(request, &parallel_part);

/* 6. Calculate controllable fraction */
norm_request = adcs_vec3_norm(request);
if (norm_request <= ADCS_EPS_NORM) {
    fraction_val = 0.0;
} else {
    fraction_val = adcs_vec3_norm(&perpendicular_part) / norm_request;
}

/* 7. Assign outputs */
*parallel = parallel_part;
*perpendicular = perpendicular_part;
*fraction = fraction_val;

/* 8. Success */
return ADCS_OK;

