if ((request == NULL) || (field == NULL) || (parallel == NULL) || 
    (perpendicular == NULL) || (fraction == NULL)) {
    return ADCS_E_NULL;
}

// 2. Validate finiteness of inputs
if (!adcs_is_finite_vec3(request) || !adcs_is_finite_vec3(field)) {
    *parallel = (adcs_vec3_t){0, 0, 0};
    *perpendicular = (adcs_vec3_t){0, 0, 0};
    *fraction = 0.0;
    return ADCS_E_NOT_FINITE;
}

// 3. Normalize the magnetic field vector to get unit vector u
double norm_field = adcs_vec3_norm(field);

// Check for degenerate field (norm <= ADCS_EPS_NORM)
if (norm_field <= ADCS_EPS_NORM) {
    *parallel = (adcs_vec3_t){0, 0, 0};
    *perpendicular = (adcs_vec3_t){0, 0, 0};
    *fraction = 0.0;
    return ADCS_E_DEGENERATE;
}

adcs_vec3_t u;
u.x = field->x / norm_field;
u.y = field->y / norm_field;
u.z = field->z / norm_field;

// 4. Compute parallel component: (request dot u) * u
double dot_val = adcs_vec3_dot(request, &u);
*parallel = adcs_vec3_scale(&u, dot_val);

// 5. Compute perpendicular component: request - parallel
*perpendicular = adcs_vec3_sub(request, parallel);

// 6. Compute controllable fraction: ||perpendicular|| / ||request||
// Special case: zero request results in fraction 0
double norm_request = adcs_vec3_norm(request);
double norm_perp = adcs_vec3_norm(perpendicular);

if (norm_request <= ADCS_EPS_NORM) {
    *fraction = 0.0;
} else {
    *fraction = norm_perp / norm_request;
}

return ADCS_OK;

